WITH i AS (SELECT $1::uuid AS job_id), j AS (
 SELECT p.* FROM public.jobs p,i WHERE p.id=i.job_id
), scenes AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
   'scene_id',s.id,'scene_number',s.scene_number,'narration',s.narration,'narration_support_evidence_ids',s.narration_support_evidence_ids,
   'beat_start_seconds',s.beat_start_seconds,'beat_end_seconds',s.beat_end_seconds,'duration_seconds',s.duration_seconds,'status',s.status,
   'visual_path',s.visual_path,'asset_count',(SELECT count(*)::int FROM public.assets a WHERE a.scene_id=s.id)
 ) ORDER BY s.scene_number),'[]'::jsonb) AS rows FROM public.scenes s,i WHERE s.job_id=i.job_id
), evidence AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
   'evidence_id',e.evidence_id,'source_id',e.source_id,'source_language',e.source_language,'source_title',e.source_title,
   'source_url',e.source_url,'passage_id',e.passage_id,'section',e.section,'evidence_text',e.evidence_text,
   'selection_score',e.selection_score,'selection_rank',e.selection_rank
 ) ORDER BY e.selection_rank),'[]'::jsonb) AS rows FROM public.job_evidence e,i WHERE e.job_id=i.job_id
), visual_state AS (
 SELECT
   (SELECT count(*)::int FROM public.visual_segments vs,i WHERE vs.job_id=i.job_id) AS segment_count,
   (SELECT count(*)::int FROM public.visual_shots sh,i WHERE sh.job_id=i.job_id) AS shot_count
)
SELECT i.job_id AS requested_job_id,j.id AS job_id,j.topic,j.language_code,j.target_duration_seconds,j.content_model_version,j.script_text,j.script_support,
       j.fact_source_language,j.fact_primary_title,j.voiceover_path,j.voiceover_duration_seconds,j.status,j.current_stage,j.id IS NOT NULL AS job_exists,
       scenes.rows AS scenes,evidence.rows AS evidence,visual_state.segment_count AS existing_visual_segment_count,visual_state.shot_count AS existing_visual_shot_count
FROM i LEFT JOIN j ON true CROSS JOIN scenes CROSS JOIN evidence CROSS JOIN visual_state;

